# Генерация «Руководство.html» для STZ WireCut. Описания кнопок берутся из src/Tips.cs
import re, html, sys
ver = sys.argv[1] if len(sys.argv) > 1 else "1.6"
src = open('../src/Tips.cs', encoding='utf-8').read()
tips = {}
for m in re.finditer(r'A\("([^"]+)",\s*"((?:[^"\\]|\\.)*)"\);', src):
    tips[m.group(1)] = m.group(2).replace('\\n', '\n').replace('\\"', '"')

def tip(c): return html.escape(tips.get(c, '')).replace('\n', '<br>')

