def ribbon():
    out = []
    for g, items in GROUPS:
        out.append('<h3>Группа «%s»</h3><table><tr><th style="width:17%%">Кнопка</th><th style="width:22%%">Команда (рус / англ)</th><th>Что делает</th></tr>' % g)
        for t, c in items:
            out.append('<tr><td><b>%s</b></td><td><code>%s</code></td><td>%s</td></tr>' % (html.escape(t), html.escape(ALIAS.get(c, c)), tip(c)))
        out.append('</table>')
    return '\n'.join(out)

