def props():
    out=[]
    for cat, rows in PROPS:
        out.append('<h3>%s</h3><table><tr><th style="width:30%%">Параметр</th><th>Пояснение</th></tr>' % html.escape(cat))
        for a,b in rows: out.append('<tr><td><b>%s</b></td><td>%s</td></tr>' % (html.escape(a), html.escape(b)))
        out.append('</table>')
    return '\n'.join(out)

